examples.sql:
SELECT d.id, item.value
FROM documents d
CROSS JOIN LATERAL jsonb_array_elements_text(d.tags) AS item(value);

SELECT p.id, s.value
FROM products p
CROSS APPLY STRING_SPLIT(p.tags, ',') s;

SELECT user_id, string_agg(skill_name, ', ' ORDER BY skill_name ASC) AS skills
FROM user_skills
GROUP BY user_id;

SELECT user_id, STRING_AGG(skill_name, ', ') WITHIN GROUP (ORDER BY skill_name ASC) AS skills
FROM user_skills
GROUP BY user_id;

SELECT date_trunc('month', created_at) AS month_start, COUNT(*) 
FROM orders 
GROUP BY date_trunc('month', created_at);

SELECT DATETRUNC(month, created_at) AS month_start, COUNT(*) 
FROM orders 
GROUP BY DATETRUNC(month, created_at);

