ON CONFLICT (tag_name) DO NOTHING;

SELECT DISTINCT ON (customer_id) customer_id, order_id, order_date, total_amount
FROM orders
ORDER BY customer_id, order_date DESC;

SELECT id, title, tags
FROM articles
WHERE tags @> ARRAY['sql', 'database'];

SELECT username, roles
FROM user_accounts
WHERE roles && ARRAY['admin', 'moderator'];

DO $$
DECLARE
    v_count INT := 0;
BEGIN
    UPDATE accounts SET balance = balance - 100 WHERE id = 1;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RAISE NOTICE 'Đã trừ tiền cho % tài khoản', v_count;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Lỗi khi cập nhật tài khoản: %', SQLERRM;
END $$;

