DECLARE @DiscountedUsers TABLE (
    user_id INT PRIMARY KEY,
    discount_pct DECIMAL(5,2)
);

INSERT INTO @DiscountedUsers (user_id, discount_pct)
SELECT id, 0.15 FROM users WHERE total_orders > 10;

SELECT u.email, d.discount_pct
FROM users u
INNER JOIN @DiscountedUsers d ON u.id = d.user_id;

CREATE OR ALTER PROCEDURE dbo.usp_ProcessOrderBatch
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE orders SET status = 'PROCESSING' WHERE status = 'PENDING';
    INSERT INTO audit_logs (log_message) VALUES ('Batch processed');
END;

